        "",
        "\t\t\t}",
        "",
        "\t\t\tif = {",
        "\t\t\t\tlimit = {",
        "\t\t\t\t\t$scale$ < 0",
        "\t\t\t\t}",
        "\t\t\t\tmax = {",
        "\t\t\t\t\tvalue = $scale$",
        "\t\t\t\t}",
        "\t\t\t\tmin = {",
        "\t\t\t\t\tvalue = 1000 # Vanilla: 10,000 (in R.P, this was 50)",
        "\t\t\t\t\tmultiply = $scale$",
        "\t\t\t\t}",
        "",
        "\t\t\t}",
        "\t\t}",
