        "\tset_variable = { name = gls_burghers_gold value = 0 }",
        "\tif = {",
        "\t\tlimit = { country_has_estate = estate_type:burghers_estate }",
        "\t\tset_variable = { name = gls_burghers_gold value = \"estate(estate_type:burghers_estate).estate_gold\" }",
        "\t}",
        "\tset_variable = { name = gls_burghers_target value = 0 }",
        "\tif = {",
        "\t\tlimit = { country_has_estate = estate_type:burghers_estate }",
        "\t\tset_variable = { name = gls_burghers_target value = { value = 100 add = { value = var:gls_country_wealth_anchor_cached multiply = 3 } min = 60 } }",
        "\t}",
        "",
        "\tset_variable = { name = gls_commoner_gold value = 0 }",
        "\tif = {",
        "\t\tlimit = { country_has_estate = estate_type:peasants_estate }",
        "\t\tset_variable = { name = gls_commoner_gold value = \"estate(estate_type:peasants_estate).estate_gold\" }",
        "\t}",
        "\tset_variable = { name = gls_commoner_target value = 0 }",
        "\tif = {",
        "\t\tlimit = { country_has_estate = estate_type:peasants_estate }",
        "\t\tset_variable = { name = gls_commoner_target value = { value = 0 add = { value = var:gls_country_wealth_anchor_cached multiply = 2 } min = 45 } }",
        "\t}",
        "",
        "\tset_variable = { name = gls_tribesmen_gold value = 0 }",
        "\tif = {",
        "\t\tlimit = { country_has_estate = estate_type:tribes_estate }",
        "\t\tset_variable = { name = gls_tribesmen_gold value = \"estate(estate_type:tribes_estate).estate_gold\" }",
        "\t}",
        "\tset_variable = { name = gls_tribesmen_target value = 0 }",
        "\tif = {",
        "\t\tlimit = { country_has_estate = estate_type:tribes_estate }",
        "\t\tset_variable = { name = gls_tribesmen_target value = { value = 0 add = { value = var:gls_country_wealth_anchor_cached multiply = 1 } min = 35 } }",
        "\t}",
        "",
        "\tset_variable = { name = gls_total_savings value = { add = var:gls_nobles_gold add = var:gls_clergy_gold add = var:gls_burghers_gold add = var:gls_commoner_gold add = var:gls_tribesmen_gold } }",
        "\tset_variable = { name = gls_total_savings_target value = { add = var:gls_nobles_target add = var:gls_clergy_target add = var:gls_burghers_target add = var:gls_commoner_target add = var:gls_tribesmen_target } }",
