        "\t\tset_variable = { name = gls_savings_pressure_adjustment value = { value = var:gls_total_savings divide = var:gls_total_savings_target subtract = 1 multiply = 0.25 max = 0.5 } }",
        "\t}",
        "}",
        "",
        "sol_count_location_estate_buildings = {",
        "\t# root = location. Cached yearly; each estate building has 1 gold maintenance.",
        "\tset_variable = { name = sol_location_estate_buildings_nobles value = 0 }",
        "\tset_variable = { name = sol_location_estate_buildings_clergy value = 0 }",
        "\tset_variable = { name = sol_location_estate_buildings_burghers value = 0 }",
        "\tset_variable = { name = sol_location_estate_buildings_commoners value = 0 }",
        "\tset_variable = { name = sol_location_estate_buildings_tribesmen value = 0 }",
        "",
        "\tevery_buildings_in_location = {",
