        "\tchange_variable = { name = sol_location_lower_base_spending add = var:sol_location_tribesmen_base_spending }",
        "\tset_variable = { name = sol_location_base_total_spending value = 0 }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_nobles_base_spending }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_clergy_base_spending }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_burghers_base_spending }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_laborers_base_spending }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_peasants_base_spending }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_soldiers_base_spending }",
        "\tchange_variable = { name = sol_location_base_total_spending add = var:sol_location_tribesmen_base_spending }",
        "",
        "\tset_variable = { name = sol_location_savings_pressure_adjustment value = 0 }",
