        "\t\t\tset_variable = { name = sol_country_demand_failure_anchor_scope value = scope:sol_demand_validation_anchor_$anchor$ }",
        "\t\t\tset_variable = { name = sol_country_demand_failure_raw value = scope:sol_demand_validation_anchor_$anchor$.var:sol_location_raw_demand_scale }",
        "\t\t\tset_variable = { name = sol_country_demand_failure_delta value = var:sol_delta_$anchor$ }",
        "\t\t\tset_variable = { name = sol_country_demand_failure_candidate value = var:sol_candidate_scale_$anchor$ }",
        "\t\t}",
        "\t\tsol_country_demand_abs = { source = sol_delta_$anchor$ target = sol_delta_abs_$anchor$ }",
        "\t\tif = { limit = { var:sol_delta_abs_$anchor$ > var:sol_country_demand_max_adjustment } set_variable = { name = sol_country_demand_max_adjustment value = var:sol_delta_abs_$anchor$ } }",
        "\t}",
        "}",
        "",
        "sol_country_demand_apply_anchor = {",
        "\tif = {",
        "\t\tlimit = { var:sol_country_demand_solve_status = 1 }",
        "\t\tvar:sol_demand_anchor_$anchor$ = {",
        "\t\t\tset_variable = { name = sol_location_final_demand_scale value = { value = var:sol_location_raw_demand_scale add = owner.var:sol_delta_$anchor$ min = 0 } }",
        "\t\t\tset_variable = { name = sol_location_pop_demand_modifier_size value = { value = var:sol_location_final_demand_scale subtract = 1 } }",
        "\t\t}",
        "\t}",
        "}",
        "",
        "sol_country_demand_fill_class_column = {",
        "\t# A class coefficient multiplies each member location's raw scale, so the matrix is raw-weighted.",
        "\tset_variable = { name = sol_m_1_$col$ value = var:sol_country_class_baseline_spending_nobles_$class$ }",
        "\tset_variable = { name = sol_m_2_$col$ value = var:sol_country_class_baseline_spending_clergy_$class$ }",
        "\tset_variable = { name = sol_m_3_$col$ value = var:sol_country_class_baseline_spending_burghers_$class$ }",
        "\tset_variable = { name = sol_m_4_$col$ value = var:sol_country_class_baseline_lower_$class$ }",
        "\tset_variable = { name = sol_m_5_$col$ value = var:sol_country_class_baseline_spending_tribesmen_$class$ }",
        "}",
        "",
        "sol_country_demand_fill_class_matrix = {",
        "\tsol_country_demand_fill_class_column = { class = 1 col = 1 }",
        "\tsol_country_demand_fill_class_column = { class = 2 col = 2 }",
        "\tsol_country_demand_fill_class_column = { class = 3 col = 3 }",
        "\tsol_country_demand_fill_class_column = { class = 4 col = 4 }",
        "\tsol_country_demand_cache_original_matrix = yes",
        "\tsol_country_demand_cache_normalized_class_matrix = yes",
        "}",
        "",
        "sol_country_demand_accumulate_score_diagnostics = {",
        "\tif = {",
        "\t\tlimit = { scope:sol_demand_cached_location.var:sol_location_baseline_total_spending > 0.00001 }",
        "\t\tchange_variable = { name = sol_country_classified_location_count add = 1 }",
        "\t\tchange_variable = { name = sol_country_class_confidence_total add = scope:sol_demand_cached_location.var:sol_location_demand_class_confidence }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_class_confidence < var:sol_country_class_confidence_min } set_variable = { name = sol_country_class_confidence_min value = scope:sol_demand_cached_location.var:sol_location_demand_class_confidence } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_class_confidence > var:sol_country_class_confidence_max } set_variable = { name = sol_country_class_confidence_max value = scope:sol_demand_cached_location.var:sol_location_demand_class_confidence } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_baseline_total_spending > var:sol_country_class_max_location_base } set_variable = { name = sol_country_class_max_location_base value = scope:sol_demand_cached_location.var:sol_location_baseline_total_spending } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_nobles < var:sol_country_class_score_min_nobles } set_variable = { name = sol_country_class_score_min_nobles value = scope:sol_demand_cached_location.var:sol_location_demand_score_nobles } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_nobles > var:sol_country_class_score_max_nobles } set_variable = { name = sol_country_class_score_max_nobles value = scope:sol_demand_cached_location.var:sol_location_demand_score_nobles } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_clergy < var:sol_country_class_score_min_clergy } set_variable = { name = sol_country_class_score_min_clergy value = scope:sol_demand_cached_location.var:sol_location_demand_score_clergy } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_clergy > var:sol_country_class_score_max_clergy } set_variable = { name = sol_country_class_score_max_clergy value = scope:sol_demand_cached_location.var:sol_location_demand_score_clergy } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_burghers < var:sol_country_class_score_min_burghers } set_variable = { name = sol_country_class_score_min_burghers value = scope:sol_demand_cached_location.var:sol_location_demand_score_burghers } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_burghers > var:sol_country_class_score_max_burghers } set_variable = { name = sol_country_class_score_max_burghers value = scope:sol_demand_cached_location.var:sol_location_demand_score_burghers } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_lower < var:sol_country_class_score_min_lower } set_variable = { name = sol_country_class_score_min_lower value = scope:sol_demand_cached_location.var:sol_location_demand_score_lower } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_lower > var:sol_country_class_score_max_lower } set_variable = { name = sol_country_class_score_max_lower value = scope:sol_demand_cached_location.var:sol_location_demand_score_lower } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_structural_class = 1 } change_variable = { name = sol_country_structural_class_count_1 add = 1 } }",
        "\t\telse_if = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_structural_class = 2 } change_variable = { name = sol_country_structural_class_count_2 add = 1 } }",
        "\t\telse_if = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_structural_class = 3 } change_variable = { name = sol_country_structural_class_count_3 add = 1 } }",
        "\t\telse_if = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_structural_class = 4 } change_variable = { name = sol_country_structural_class_count_4 add = 1 } }",
        "\t}",
        "}",
        "",
        "sol_country_demand_cache_normalized_class_row = {",
        "\tset_variable = { name = sol_normalized_m_$row$_1 value = 0 }",
        "\tset_variable = { name = sol_normalized_m_$row$_2 value = 0 }",
        "\tset_variable = { name = sol_normalized_m_$row$_3 value = 0 }",
        "\tset_variable = { name = sol_normalized_m_$row$_4 value = 0 }",
        "\tif = {",
        "\t\tlimit = { var:$scale$ > 0.00001 }",
        "\t\tset_variable = { name = sol_normalized_m_$row$_1 value = { value = var:sol_original_m_$row$_1 divide = var:$scale$ } }",
        "\t\tset_variable = { name = sol_normalized_m_$row$_2 value = { value = var:sol_original_m_$row$_2 divide = var:$scale$ } }",
        "\t\tset_variable = { name = sol_normalized_m_$row$_3 value = { value = var:sol_original_m_$row$_3 divide = var:$scale$ } }",
        "\t\tset_variable = { name = sol_normalized_m_$row$_4 value = { value = var:sol_original_m_$row$_4 divide = var:$scale$ } }",
