        "\t\tset_variable = { name = sol_m_$row$_2 value = { value = var:sol_m_$row$_2 divide = var:$scale$ } }",
        "\t\tset_variable = { name = sol_m_$row$_3 value = { value = var:sol_m_$row$_3 divide = var:$scale$ } }",
        "\t\tset_variable = { name = sol_m_$row$_4 value = { value = var:sol_m_$row$_4 divide = var:$scale$ } }",
        "\t\tset_variable = { name = sol_b_$row$ value = { value = var:sol_b_$row$ divide = var:$scale$ } }",
        "\t}",
        "}",
