        "\tsol_country_demand_normalize_working_class_row = { row = 1 scale = sol_country_baseline_spending_nobles }",
        "\tsol_country_demand_normalize_working_class_row = { row = 2 scale = sol_country_baseline_spending_clergy }",
        "\tsol_country_demand_normalize_working_class_row = { row = 3 scale = sol_country_baseline_spending_burghers }",
