        "\t\t\tset_variable = { name = sol_country_class_example_$class$ value = scope:sol_demand_cached_location }",
        "\t\t\tset_variable = { name = sol_country_class_example_base_$class$ value = scope:sol_demand_cached_location.var:sol_location_base_total_spending }",
