        "\t\t}",
        "\t}",
        "}",
        "",
        "sol_country_demand_measure_class_profile = {",
        "\tset_variable = { name = sol_country_class_score_nobles_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_score_clergy_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_score_burghers_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_score_lower_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_signature_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_cross_score_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_signature_margin_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_base_share_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_base_deviation_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_affinity_avg_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_penalty_avg_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_confidence_avg_$class$ value = 0 }",
        "\tset_variable = { name = sol_country_class_structural_match_rate_$class$ value = 0 }",
        "\tif = { limit = { var:sol_country_baseline_spending_total > 0.00001 } set_variable = { name = sol_country_class_base_share_$class$ value = { value = var:sol_country_class_baseline_total_$class$ divide = var:sol_country_baseline_spending_total } } }",
        "\tif = { limit = { var:sol_country_class_target_capacity_$class$ > 0.00001 } set_variable = { name = sol_country_class_base_deviation_$class$ value = { value = var:sol_country_class_baseline_total_$class$ subtract = var:sol_country_class_target_capacity_$class$ divide = var:sol_country_class_target_capacity_$class$ } } }",
        "\tif = {",
        "\t\tlimit = { var:sol_country_class_count_$class$ > 0 }",
        "\t\tset_variable = { name = sol_country_class_affinity_avg_$class$ value = { value = var:sol_country_class_affinity_total_$class$ divide = var:sol_country_class_count_$class$ } }",
        "\t\tset_variable = { name = sol_country_class_penalty_avg_$class$ value = { value = var:sol_country_class_penalty_total_$class$ divide = var:sol_country_class_count_$class$ } }",
        "\t\tset_variable = { name = sol_country_class_confidence_avg_$class$ value = { value = var:sol_country_class_confidence_total_$class$ divide = var:sol_country_class_count_$class$ } }",
        "\t\tset_variable = { name = sol_country_class_structural_match_rate_$class$ value = { value = var:sol_country_class_structural_match_count_$class$ divide = var:sol_country_class_count_$class$ } }",
        "\t}",
        "\tif = {",
        "\t\tlimit = { var:sol_country_class_base_total_$class$ > 0.00001 }",
        "\t\tset_variable = { name = sol_country_class_score_nobles_$class$ value = { value = var:sol_country_class_base_spending_nobles_$class$ divide = var:sol_country_class_base_total_$class$ subtract = var:sol_country_share_nobles divide = var:sol_country_class_normalizer_nobles } }",
        "\t\tset_variable = { name = sol_country_class_score_clergy_$class$ value = { value = var:sol_country_class_base_spending_clergy_$class$ divide = var:sol_country_class_base_total_$class$ subtract = var:sol_country_share_clergy divide = var:sol_country_class_normalizer_clergy } }",
        "\t\tset_variable = { name = sol_country_class_score_burghers_$class$ value = { value = var:sol_country_class_base_spending_burghers_$class$ divide = var:sol_country_class_base_total_$class$ subtract = var:sol_country_share_burghers divide = var:sol_country_class_normalizer_burghers } }",
        "\t\tset_variable = { name = sol_country_class_score_lower_$class$ value = { value = var:sol_country_class_base_lower_$class$ divide = var:sol_country_class_base_total_$class$ subtract = var:sol_country_share_lower divide = var:sol_country_class_normalizer_lower } }",
        "\t\tset_variable = { name = sol_country_class_signature_$class$ value = var:$signature$ }",
        "\t\tset_variable = { name = sol_country_class_cross_score_$class$ value = var:$cross_1$ }",
        "\t\tif = { limit = { var:$cross_2$ > var:sol_country_class_cross_score_$class$ } set_variable = { name = sol_country_class_cross_score_$class$ value = var:$cross_2$ } }",
        "\t\tif = { limit = { var:$cross_3$ > var:sol_country_class_cross_score_$class$ } set_variable = { name = sol_country_class_cross_score_$class$ value = var:$cross_3$ } }",
        "\t\tset_variable = { name = sol_country_class_signature_margin_$class$ value = { value = var:sol_country_class_signature_$class$ subtract = var:sol_country_class_cross_score_$class$ } }",
