        "}",
        "",
        "sol_country_demand_validate_class_residual = {",
        "\tset_variable = { name = sol_country_class_residual_$row$ value = { value = var:sol_country_demand_lhs_$row$ subtract = var:$rhs$ } }",
        "\tsol_country_demand_abs = { source = sol_country_class_residual_$row$ target = sol_country_class_residual_abs_$row$ }",
        "\tset_variable = { name = sol_country_class_residual_tolerance_$row$ value = { value = var:$rhs$ multiply = 0.001 add = 0.01 } }",
        "\tif = {",
