        "\t\t\t}",
        "\t\t\tsol_country_demand_cmf_log = { action = CMF_LOG_SOL_DEMAND_DETAIL_SUMMARY_ACTION detail = CMF_LOG_SOL_DEMAND_DETAIL_SUMMARY }",
        "\t\t\tsol_country_demand_cmf_log = { action = CMF_LOG_SOL_DEMAND_DETAIL_FAILURE_ACTION detail = CMF_LOG_SOL_DEMAND_DETAIL_FAILURE_SCALE }",
        "\t\t\tsol_country_demand_log_anchor_rows = yes",
