        ("class_target_capacity_3", "sol_country_class_target_capacity_3"),
        ("class_target_capacity_4", "sol_country_class_target_capacity_4"),
        ("class_negative_pressure_1", "sol_country_class_negative_pressure_1"),
        ("class_negative_pressure_2", "sol_country_class_negative_pressure_2"),
        ("class_negative_pressure_3", "sol_country_class_negative_pressure_3"),
        ("class_negative_pressure_4", "sol_country_class_negative_pressure_4"),
        ("class_balance_weight", "sol_country_class_balance_weight"),
